  "fund.empty.text": "Önce bir kasa oluştur ve kimin ait olduğunu seç – ör. yalnızca ebeveynler için bir ev kasası, herkes için bir ortak ev kasası veya yalnızca senin için bir kasa. Üye olmayanlar bu kasanın ne işlemlerini ne birikimlerini, ne de sözleşmelerini veya belgelerini görür.",
