  "fund.splitHint": "Ortak evler, tatiller vb. için: her gider ödeyen kişi için sayılır ve seçilen üyeler arasında bölüştürülür. Giderlerin en üstünde kimin kime ne kadar borçlu olduğunu görürsün – “Hesaplaş” ile.",
