  "loc.enterShopAddressesUnder": "Mağaza adreslerini Listeler → Alışveriş listesini düzenle altında girersin – bir mağaza birden fazla yerde varsa birden çok şube de. Biri orada bir süre kalırsa planlanan alışveriş gezisi işaretlenir.",
