  "loc.gpsTracker": "🛰️ GPS takip cihazı",
  "loc.guide1": "<b>“Traccar Client”</b> uygulamasını yükle (App Store veya Google Play, ücretsiz).",
  "loc.guide2": "Uygulamada <b>Device ID</b> (Cihaz tanımlayıcısı) altına gir:",
  "loc.guide3": "<b>Server URL</b> altına gir:",
  "loc.guide4": "Doğruluk <b>Medium</b>, mesafe <b>50 m</b>. Uygulama o zaman yalnızca hareket ettiğinde gönderir – dururken hiçbir şey göndermez. Daha fazla alanın varsa (aralık, heartbeat), heartbeat'i kapat veya 0 yap.",
  "loc.guide5": "Konum erişimine izin ver: <b>Always</b> ve <b>Precise Location</b> açık.",
  "loc.guide6": "<b>Service / Tracking</b> düğmesini aç ve <b>her zaman açık bırak</b> – bu kadar. Bundan sonra her şeyi pinn.'de yönetirsin: “Sürekli gönder” açık veya kapalı, “Bir kez gönder” ve SOS. “Sürekli gönder” kapalı olduğu sürece kimse konumunu görmez ve pinn. rota kaydetmez.",
  "loc.guideIntro": "Başka bir uygulama olmadan “📍 Konumu paylaş” doğrudan pinn.'de çalışır – ama yalnızca pinn. açıkken. Konumun pinn. kapalıyken ve ekran kilitliyken de ulaşması için ücretsiz “Traccar Client” uygulaması onu doğrudan pinn.'e gönderir (Traccar sunucusu gerekmez). iPhone ve Android için aynı.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. Takip cihazı mobil ağdan bağlandığı için bu port FRITZ!Box'ta NAS'a yönlendirilmelidir.",
  "loc.haveGoodTripFamily": "İyi yolculuklar! Aile bilgilendirildi.",
