  "loc.ifSomeoneArrivesLeaves": "Biri bir yere vardığında veya o yerden ayrıldığında anlık bildirim gelir. “Ev” ayrıca “Eve dönüyorum”u bitirir.",
  "loc.ifTrackerHasSos": "Takip cihazında SOS düğmesi varsa, Traccar cihazın alarmını algılar algılamaz pinn. (bir dakika içinde) tüm aileye anlık bildirimle haber verir.",
  "loc.ifTrackerHasSos#wg": "Takip cihazında SOS düğmesi varsa, Traccar cihazın alarmını algılar algılamaz pinn. (bir dakika içinde) tüm ortak eve anlık bildirimle haber verir.",
