  "voice.widgetIntro": "Randevuları, görevleri ve alışveriş listesini ana ekranda ve saatte gösterir – yalnızca okuma. Yukarıdakiyle aynı gizli bağlantı kullanılır.",
  "voice.widgetIos1": "App Store'dan ücretsiz <b>Scriptable</b> uygulamasını yükleyin, açın ve sağ üstteki <b>+</b> simgesine dokunun.",
  "voice.widgetIos2": "pinn. içinde “Widget betiğini kopyala”ya dokunun, metni Scriptable'a yapıştırın ve betiği <b>pinn</b> olarak adlandırın.",
  "voice.widgetIos3": "Ana ekrana uzun basın → <b>+</b> → <b>Scriptable</b> → boyut seçin → widget'a dokunun → “Script” alanında <b>pinn</b> seçin. iOS yaklaşık her 15 dakikada bir yeniler.",
  "voice.widgetIosTitle": "Scriptable ile iPhone widget'ı",
  "voice.widgetNeedOne": "Lütfen en az bir seçenek işaretleyin.",
  "voice.widgetNote": "Siri'de olduğu gibi iPhone'un pinn.'e ulaşabilmesi gerekir (evdeki Wi-Fi veya VPN). Bağlantı bir parola gibi çalışır – paylaşmayın.",
  "voice.widgetPick": "Widget ne göstersin? İşaretleyin, ardından betiği kopyalayın – her widget için ayrı bir betik.",
  "voice.widgetQuickCopy": "🔗 Hızlı erişim betiğini kopyala",
  "voice.widgetQuickHint": "Hızlı erişim: üç düğmeli bir widget – listeler, finans (bölgenin para birimi simgesiyle) ve görevler. Dokunmak, pinn.’in ilgili sayfasını yüklü uygulamada değil Safari’de açar; orada bir kez oturum açın.",
  "voice.widgetScriptCopied": "Betik kopyalandı.",
  "voice.widgetTasks": "Görevler (ev işleri hariç)",
  "voice.widgetTick": "Orta ve büyük widget’ta bir göreve dokunarak işaretleyin – pinn.’de de işaretlenir. iOS bunun için Scriptable’ı kısaca açar.",
  "voice.widgetTitle": "📲 Widget'lar ve ⌚ Apple Watch",
  "voice.widgetViews": "Başka görünüm: bağlantıdaki <code>ansicht=heute</code> yerine <code>morgen</code>, <code>einkauf</code> veya <code>alles</code> yazın.",
  "voice.widgetWatch1": "iPhone'daki <b>Kısayollar</b> uygulamasında yeni bir kısayol oluşturup <b>“URL İçeriğini Al”</b> eylemini ekleyin.",
  "voice.widgetWatch2": "Burada “Kısayol için bağlantıyı kopyala”ya dokunun ve URL olarak yapıştırın (yöntem GET).",
