  "voice.widgetWatch4": "<b>ⓘ</b> simgesine dokunun, <b>Apple Watch'ta Göster</b>'i açın ve kısayola örneğin <b>pinn bugün</b> adını verin. Saatte Kısayollar uygulamasından başlatın veya “Hey Siri, pinn bugün” deyin.",
